cd /home/user/fortress-tabulate && cat > tmp/helpers.sh <<'EOF'
run_bg () {
    nohup bash -c "( $2 ) > '$1' 2>&1; echo EXIT=\$? >> '$1'" >/dev/null 2>&1 &
}
wait_for () {
    local n=0
    while ! grep -q '^EXIT=' "$1" 2>/dev/null ; do
        sleep 5 ; n=$((n+5))
        [ "$n" -ge "${2:-480}" ] && { echo "still running after ${n}s" ; return 1 ; }
    done
    grep -n '^BUILD \|^Total time:\|^EXIT=' "$1"
}
setup () {
    cd /home/user/fortress-tabulate
    source explorations/experiment/env.sh
    export TMPDIR=/home/user/fortress-tabulate/tmp
    export JAVA_FLAGS="-Xmx4g -Xss64m -Djava.io.tmpdir=/home/user/fortress-tabulate/tmp"
    export JAVA_HOME=/usr/lib/jvm/java-25-openjdk-amd64
    export PATH=$JAVA_HOME/bin:$PATH
    unset JAVA_TOOL_OPTIONS
}
EOF
cat explorations/experiment/env.sh

